package org.sleepwell.app;
import java.time.*;import java.util.*;import org.json.*;
/** User-entered reusable one-date profiles. No presets or recurring schedule authority. */
final class NapProfiles {
 static final class Entry {final int minute,duration;Entry(int minute,int duration){if(minute<0||minute>=1440||duration<1||duration>600)throw new IllegalArgumentException("Choose a valid start and 1–600 minute duration.");this.minute=minute;this.duration=duration;}JSONObject json()throws JSONException{return new JSONObject().put("minute",minute).put("duration",duration);}static Entry read(JSONObject j)throws JSONException{if(j.length()!=2)throw new JSONException("Invalid profile entry");return new Entry(number(j,"minute"),number(j,"duration"));}}
 static final class Profile {final String id,name;final int revision;final List<Entry> entries;Profile(String id,String name,int revision,List<Entry> entries){uuid(id);if(name==null||name.length()>120)throw new IllegalArgumentException("Choose a profile name.");String clean=name.replaceAll("[\\p{Cntrl}\\p{Cf}\\p{Zl}\\p{Zp}]"," ").strip();if(clean.isEmpty()||clean.codePointCount(0,clean.length())>60||revision<0||entries==null||entries.size()<2||entries.size()>6)throw new IllegalArgumentException("Use a name and 2–6 entries.");List<Entry> sorted=new ArrayList<>(entries);sorted.sort(Comparator.comparingInt(e->e.minute));for(int n=1;n<sorted.size();n++)if(sorted.get(n-1).minute+sorted.get(n-1).duration>sorted.get(n).minute)throw new IllegalArgumentException("Profile entries must not overlap.");this.id=id;this.name=clean;this.revision=revision;this.entries=List.copyOf(sorted);}JSONObject json()throws JSONException{JSONArray values=new JSONArray();for(Entry e:entries)values.put(e.json());return new JSONObject().put("id",id).put("name",name).put("revision",revision).put("entries",values);}static Profile read(JSONObject j)throws JSONException{if(j.length()!=4)throw new JSONException("Invalid profile");List<Entry> entries=new ArrayList<>();JSONArray a=j.getJSONArray("entries");for(int n=0;n<a.length();n++)entries.add(Entry.read(a.getJSONObject(n)));return new Profile(j.getString("id"),j.getString("name"),number(j,"revision"),entries);}}
 static final class Review {final Profile profile;final LocalDate day;final ZoneId zone;final long wall,elapsed,boot;final String device;final List<Long> starts;
  Review(Profile profile,LocalDate day,ZoneId zone,long wall,long elapsed,long boot,String device){if(profile==null||day==null||zone==null||wall<=0||elapsed<0||boot<0||device==null||device.isEmpty()||device.length()>80)throw new IllegalArgumentException("Profile review is unreadable.");LocalDate today=Instant.ofEpochMilli(wall).atZone(zone).toLocalDate();if(day.isBefore(today)||day.isAfter(today.plusDays(366)))throw new IllegalArgumentException("Choose a date within the next year.");this.profile=profile;this.day=day;this.zone=zone;this.wall=wall;this.elapsed=elapsed;this.boot=boot;this.device=device;List<Long> times=new ArrayList<>();for(Entry entry:profile.entries){LocalDateTime local=day.atTime(entry.minute/60,entry.minute%60);List<ZoneOffset> offsets=zone.getRules().getValidOffsets(local);if(offsets.size()!=1)throw new IllegalArgumentException("A start time is skipped or repeated on this date. Choose another date or time.");long at=local.toInstant(offsets.get(0)).toEpochMilli();if(at-wall<60000)throw new IllegalArgumentException("Every nap must start at least one minute in the future. Choose a later date or time.");times.add(at);}for(int n=1;n<times.size();n++)if(times.get(n-1)+profile.entries.get(n-1).duration*60000L>times.get(n))throw new IllegalArgumentException("These nap intervals overlap after this date’s clock change. Choose different times or durations.");starts=List.copyOf(times);}
  void check(NapPlan.Clock now,ZoneId current){long drift=(now.wall()-wall)-(now.elapsed()-elapsed);if(!zone.equals(current)||boot!=now.boot()||!device.equals(now.device())||now.elapsed()<elapsed||drift>2000||drift< -2000)throw new IllegalArgumentException("Phone time, zone or boot changed. Review the profile again.");for(long start:starts)if(start-now.wall()<60000)throw new IllegalArgumentException("A start is too close or passed. Review a later date.");}
  JSONObject json()throws JSONException{return new JSONObject().put("profile",profile.json()).put("day",day.toString()).put("zone",zone.getId()).put("wall",wall).put("elapsed",elapsed).put("boot",boot).put("device",device);}static Review read(JSONObject j)throws JSONException{return new Review(Profile.read(j.getJSONObject("profile")),LocalDate.parse(j.getString("day")),ZoneId.of(j.getString("zone")),j.getLong("wall"),j.getLong("elapsed"),j.getLong("boot"),j.getString("device"));}}
 static final class Row {final int id;final String snapshot;final boolean scheduled,cancelled;Row(int id,String snapshot,boolean scheduled,boolean cancelled){if(id<=0||snapshot==null||snapshot.length()>32768)throw new IllegalArgumentException("Invalid profile ownership row.");try{Alarm a=Alarm.read(new JSONObject(snapshot));if(a.id!=id||a.nap==null||a.napInvalid)throw new IllegalArgumentException("Invalid profile timer.");}catch(JSONException bad){throw new IllegalArgumentException("Invalid profile timer.");}this.id=id;this.snapshot=snapshot;this.scheduled=scheduled;this.cancelled=cancelled;}Alarm alarm(){try{return Alarm.read(new JSONObject(snapshot));}catch(JSONException impossible){throw new IllegalArgumentException("Invalid profile timer.");}}Row scheduled(){return new Row(id,snapshot,true,cancelled);}Row snapshot(String raw){return new Row(id,raw,scheduled,cancelled);}Row cancelled(){return new Row(id,snapshot,scheduled,true);}JSONObject json()throws JSONException{return new JSONObject().put("id",id).put("snapshot",snapshot).put("scheduled",scheduled).put("cancelled",cancelled);}static Row read(JSONObject j)throws JSONException{if(j.length()!=4||!(j.get("scheduled") instanceof Boolean)||!(j.get("cancelled") instanceof Boolean))throw new JSONException("Invalid profile ownership row");return new Row(number(j,"id"),j.getString("snapshot"),j.getBoolean("scheduled"),j.getBoolean("cancelled"));}}
 static final class Batch {final String id,stage,error;final Review review;final List<Row> rows;final boolean activation,cancellation;Batch(String id,Review review,List<Row> rows,String stage,String error,boolean activation,boolean cancellation){uuid(id);if(review==null||rows==null||rows.size()!=review.profile.entries.size()||!Set.of("PREPARED","CREATED","SCHEDULING","ACTIVATING","SCHEDULED","CANCELLING","CANCELLED","ATTENTION").contains(stage)||error==null||error.length()>300)throw new IllegalArgumentException("Invalid profile application.");Set<Integer> ids=new HashSet<>();for(Row row:rows)if(!ids.add(row.id))throw new IllegalArgumentException("Duplicate profile timer.");this.id=id;this.review=review;this.rows=List.copyOf(rows);this.stage=stage;this.error=error;this.activation=activation;this.cancellation=cancellation;}Batch change(List<Row> rows,String stage,String error,boolean activation,boolean cancellation){return new Batch(id,review,rows,stage,error,activation,cancellation);}JSONObject json()throws JSONException{JSONArray values=new JSONArray();for(Row row:rows)values.put(row.json());return new JSONObject().put("id",id).put("review",review.json()).put("rows",values).put("stage",stage).put("error",error).put("activation",activation).put("cancellation",cancellation);}static Batch read(JSONObject j)throws JSONException{if(j.length()!=7||!(j.get("activation") instanceof Boolean)||!(j.get("cancellation") instanceof Boolean))throw new JSONException("Invalid profile application");List<Row> rows=new ArrayList<>();JSONArray a=j.getJSONArray("rows");for(int n=0;n<a.length();n++)rows.add(Row.read(a.getJSONObject(n)));return new Batch(j.getString("id"),Review.read(j.getJSONObject("review")),rows,j.getString("stage"),j.getString("error"),j.getBoolean("activation"),j.getBoolean("cancellation"));}}
 static int number(JSONObject j,String key)throws JSONException{Object value=j.get(key);if(!(value instanceof Number n)||!Double.isFinite(n.doubleValue())||n.doubleValue()!=Math.rint(n.doubleValue())||n.doubleValue()<Integer.MIN_VALUE||n.doubleValue()>Integer.MAX_VALUE)throw new JSONException("Expected whole number");return n.intValue();}
 static void uuid(String value){if(value==null||!UUID.fromString(value).toString().equals(value))throw new IllegalArgumentException("Invalid profile identity.");}
 private NapProfiles(){}
}
